      ollamaAirgap: { id: 'ollama-airgap', title: 'Ollama air-gapワークフロー', content: 'オフラインマシンへのファイル転送後：', numberedItems: ['`~/.ollama/`ディレクトリ全体をオフラインホストの同じパスにコピー。', 'バイナリインストール：`chmod +x ollama && sudo mv ollama /usr/local/bin/`', 'モデルディレクトリ設定：`export OLLAMA_MODELS=/path/to/models`', 'サーバー起動：`ollama serve` — ログでネットワーク呼び出しなしを確認。', 'オフラインテスト：`ollama run qwen2.5:14b`'] },
      llamacppAirgap: { id: 'llamacpp-airgap', title: 'llama.cpp air-gapワークフロー', content: 'バイナリ + GGUF後、llama.cppは完全に自己完結。', items: ['バイナリとGGUFをオフラインマシンに転送。', '実行：`./llama-server -m ./qwen2.5-14b-instruct-q4_K_M.gguf --port 8080`', 'OpenAI互換API：`http://localhost:8080/v1`'] },
